-- Supabase query_logs enforces project yvwpchffctiagevpqgwy and UTC 2026-11-03 04:24:00 to 04:34:00.
-- User-agent families are coarse classification, not verified user identities.
SELECT multiIf(position(log_attributes['request.headers.user_agent'],'Dart')>0,'Dart',position(log_attributes['request.headers.user_agent'],'Mozilla')>0,'browser',position(log_attributes['request.headers.user_agent'],'Deno')>0,'Deno','other') AS client_family,splitByChar('?',log_attributes['request.path'])[1] AS path,log_attributes['request.method'] AS method,count() AS n,round(quantileExact(0.95)(toFloat64OrZero(log_attributes['response.origin_time'])),1) AS p95_ms,max(toFloat64OrZero(log_attributes['response.origin_time'])) AS max_ms,countIf(position(decodeURLComponent(log_attributes['request.search']),'account_status,current_lat,current_lng,last_location_updated_at,rating,kyc_id')>0) AS live_map_projection_matches FROM logs WHERE source='edge_logs' AND (splitByChar('?',log_attributes['request.path'])[1] IN ('/rest/v1/riders','/rest/v1/rider_kyc','/rest/v1/payments','/rest/v1/orders','/rest/v1/rider_withdrawals','/rest/v1/admins','/rest/v1/rpc/get_dashboard_stats','/rest/v1/rpc/get_revenue_stats')) GROUP BY client_family,path,method ORDER BY n DESC
